from layout import *
NAMES={'none':'Без записи','recent':'Последние наблюдения','center':'Участок вокруг той же строки','bundle':'Инструкция и заголовки','full':'Весь файл','gate':'Условный выбор формата'}
ORDER=('none','recent','center','bundle','full','gate')
def interval(x,digits=2):
    return 'от '+pp(x[0],digits)+' до '+pp(x[1],digits)

def human():
    page('Редактирование с локальной Qwen','Помогает ли структурированная записка исправить программу',
         'Достоинство заметки проверяли исполняемым результатом. После очистки диалога Qwen могла сразу отредактировать файл либо один раз запросить весь его текст.')
    p('Из 164 Python-задач HumanEvalPack условиям по размеру, синтаксису и разрешённым операциям соответствовали 111. Первые 48 по заранее выбранному хешу вошли в основную часть. Модель сначала читала неисправный код, указывала подозрительную строку. Инструменты читали соседние пять строк и запускали опубликованные примеры. В новом диалоге всем вариантам давали одно описание и один возможный повторный запрос файла.')
    p('Предложенное правило сохраняло инструкцию Python с выбранной строкой, затем окружающие управляющие заголовки и соседние строки до 80 токенов. Сильнейший заранее определённый контроль сохранял непрерывный участок вокруг той же строки при идентичном лимите. «Весь файл» снимает ограничение. Порядок прогонов перемешан, температура 0, скрытые тесты доступны только после фиксации ответов.')
    d=J('live/corrected_results.json');rows=d['all']['rows'];tbl(['Запись','Прошли тесты','Сразу, без READ','Повторные чтения'],[[NAMES[a],str(rows[a]['solves'])+' / 48',n(rows[a]['first_solves']),n(rows[a]['rereads'])] for a in ORDER[:5]],[6.0,3.7,3.9,3.5],True)
    x=d['all']['paired']['bundle-center-hit'];f=d['all']['paired']['bundle-center-first_hit']
    p(f"В сравнении с непрерывным участком получено {x['wins']} выигрышей и {x['losses']} проигрышей, разность {pp(x['mean_delta'],2)} п.п. (95% ДИ {interval(x['ci95'])}). Точный двусторонний p Мак-Немара {dec(x['exact_p'],3)}. Для успеха сразу после паузы разность {pp(f['mean_delta'],2)} п.п.")
    dd=J('live/derived.json')['cohorts']['primary']['prefix_diagnostics']
    p(f"В {dd['same_bundle_center']} задачах обе краткие записи оказались побайтово одинаковыми. В {dd['same_center_full']} задачах весь файл поместился в непрерывный участок. Исходный неисправный вариант прошёл {rows['buggy']['solves']}/48 авторских наборов, эталонный — {rows['canonical']['solves']}/48. Знаменатель основной проверки сохранён заранее.")
    p('При отсутствии расходящихся пар обычный парный bootstrap даёт вырожденный интервал [0; 0]. Он описывает наблюдавшуюся выборку и не доказывает равенства двух методов в популяции. Средний размер записки с инструкцией составил 71,4 токена, непрерывной записки — 68,2.')
    p('Таблица учитывает исправление оболочки после первой оценки. Изначально две авторские функции-помощника не попадали в область видимости теста. До исправления обе записи давали 42/48 на первой части и 53/63 против 52/63 на второй. После повторной оценки тех же файлов эталон проходит на всех 111 задачах.')
    source('HumanEvalPack · зафиксированная версия исходных функций и тестов','https://huggingface.co/datasets/bigcode/humanevalpack/tree/9a41762f73a8cb23bb5811b73d5aab164efcf378')

def plus():
    page('Воспроизводимость эффекта на новых задачах','Перенос на оставшиеся функции и усиленные тесты',
         'Оставшиеся 63 подходящие задачи попали во вторую проверку до открытия оценок на первых 48. Усиленные тесты отдельно проверяют те же физически сохранённые исправления.')
    a=J('live/corrected_results.json');b=J('live/transfer/corrected_results.json');pa=J('live/evalplus_results.json');pb=J('live/transfer/evalplus_results.json')
    cols=[['Формат записи','Исходные 48','EvalPlus 48','Исходные 63','EvalPlus 63']]
    tab=[]
    for k in ORDER[:5]:
        tab.append([NAMES[k],n(a['all']['rows'][k]['solves']),n(pa['primary']['arms'][k]['plus_solves']),n(b['all']['rows'][k]['solves']),n(pb['primary']['arms'][k]['plus_solves'])])
    tbl(cols[0],tab,[5.7,2.85,2.85,2.85,2.85],True)
    x=b['all']['paired']['bundle-center-hit'];q=pb['primary']['paired_vs_center']['plus_hit']
    p(f"На 63 функциях разность между структурированной запиской и непрерывным участком составила {pp(x['mean_delta'],2)} п.п. по исходным тестам (95% ДИ {interval(x['ci95'])}, W/L {x['wins']}/{x['losses']}). На усиленных тестах разность {pp(q['mean_delta'],2)} п.п. (W/L {q['wins']}/{q['losses']}). Всего усиленный набор удалось сопоставить с {pa['primary']['n']} и {pb['primary']['n']} функциями по номеру и имени точки входа.")
    p('На второй части семь проходивших базовые тесты исправлений у структурированной записки и пять у непрерывного участка провалили усиленные тесты. Обратных переходов у этих двух методов здесь не было. Так исходная разница 54 против 52 сменилась равенством 47 против 47.')
    p(f"Правило, включающее структурированную запись только при пропущенном управляющем заголовке, использовало её в {a['gate_used']} и {b['gate_used']} случаях. Оно дало {a['all']['rows']['gate']['solves']}/48 и {b['all']['rows']['gate']['solves']}/63 по исходным тестам. Это объединение уже выполненных ветвей по известному до оценки правилу.")
    p('Например, words_in_sentence (Python/143) прошла исходные тесты сразу со структурированной запиской, а непрерывный участок привёл к повторному чтению и неудачной правке. Для select_words (Python/117) непрерывный участок с повторным чтением помог, а непосредственная правка после структурированной записки провалилась.')
    ca=J('live/derived.json')['actual']
    p(f"С выбором фокусной строки было выполнено {n(ca['calls'])} различных запросов Qwen, {n(ca['prompt_tokens'])} входных и {n(ca['completion_tokens'])} выходных токенов. Одинаковый полный запрос внутри выборки использовал один ответ. Стоимость каждой политики при отдельном запуске записана в построчных логах.")
    p(f"Контроль чувствительности для усиленных тестов (эталон проходит и неисправный код падает) оставляет {pa['sensitivity']['n']} и {pb['sensitivity']['n']} задач. Публичные задачи могли быть знакомы модели. Пауза, интерфейс одной замены, ограничения исполнения и отбор функций изменяют исходную постановку HumanEvalFix.")
    p('При независимом повторении на сохранённых программах совпали 407/407 исходов базовых тестов и 406/407 исходов HumanEval+. На функции prime_fib вариант без записи во второй раз уложился в 5 секунд, что изменило его счёт с 50 до 51 из 63. Для двух основных записей сохранилось равенство 41/48 и 47/63. При исключении задач с таймаутами получили 40 против 40 из 45 и 45 против 43 из 56 (p = 0,727 на второй части).')
    source('Исходный интерфейс оценки HumanEvalFix · BigCode','https://github.com/bigcode-project/bigcode-evaluation-harness/blob/8fc5bae6479c4fbbb28c3f8b644f6a15b3f3b5bd/bigcode_eval/tasks/humanevalpack.py')
    source('Дополнительные исполняемые тесты · EvalPlus','https://github.com/evalplus/evalplus')

def realpacket():
    page('Собственные действия Qwen на SWE-smith','Можно ли применить правку после передачи памяти',
         'Из одних и тех же наблюдений собрали две записки по 512 токенов. В каждой ветви Qwen сама предлагала один новый вызов редактирования.')
    p('Этот пилот проводился после просмотра результатов поиска. Кандидатов упорядочили по хешу. Брали состояния, в которых удалось восстановить ранее прочитанный Python-файл. Из первых 160 кандидатов сформировали 32 состояния. Для обоих методов фиксировались условие, путь и одно действие. Эталонное изменение и будущий ответ исторического редактора оставались у оценщика.')
    d=J('packets/live/results.json');tab=[]
    for k,s in [('has_action','Предложена замена текста'),('unique','Старый текст встретился один раз'),('ast_change','Применима правка с изменением AST'),('exact_reference_repair','Восстановлено эталонное дерево'),('exact_history','Точное совпадение с исторической правкой')]:
        r=d[k];tab.append([s,n(r['n']),n(r['success']['rebased_tail']),n(r['success']['joint']),str(r['wins'])+' / '+str(r['losses'])])
    tbl(['Что сделал редактор','N','Хвост','Совместно','W / L'],tab,[7.9,1.5,2.1,2.8,2.8],True)
    x=d['ast_change']
    p(f"Первичный исход — старая строка присутствовала ровно один раз, подстановка меняла синтаксическое дерево и оставляла файл разбираемым. Разность {pp(x['difference'],2)} п.п., 95% ДИ по {x['repo_clusters']} репозиториям {interval(x['ci95'])}. Побайтово одинаковую историю читатель получил в {d['identical_messages_pairs']} парах.")
    p('Восстановление исходного дерева проверялось только там, где эталонное состояние доступно и действительно отличалось до новой правки. Несколько различных корректных решений могут иметь разные деревья. Совпадение с исторической заменой проверялось только для того же файла. Статический парсер и проверки уникальности не оценивают, исправила ли программа исходную ошибку.')
    p('На части состояний исходный файл уже имел эталонное дерево перед вмешательством. Несмотря на это, вариант с цельными участками изменил такое дерево в двух случаях, а хвост — в трёх. По менее строгой метрике применимости оба результата были бы записаны как успешные действия.')
    p('На 64 отдельных вызовах Qwen сообщения двух методов в среднем содержали 479 и 482 токена. Сопоставим и суммарный объём запросов с ответами — 34 450 токенов у цельных участков и 34 443 у хвоста.')
    p('Снимок получен из версии проекта и известных предшествующих замен. У произвольных команд в истории могли быть незафиксированные эффекты. Тесты проекта для новых исправлений здесь не запускались. Это прямой пилот действия читателя на коде из репозитория, с отдельной неопределённостью качества снимка.')
    source('Как получены исходные траектории и репозитории · SWE-smith','https://swesmith.com/')

